def check_condition_full(x, n_min, d_min, n_max_range, d_max_range):
    for n in range(n_min, n_max_range + 1):
        for d in range(d_min, d_max_range + 1):
            idx2nd = 2*n + d
            idxnd = n + d
            idxn = n
            if idx2nd >= len(x):
                continue
            val1 = x[idx2nd] - x[idxnd] - n
            val2 = x[idx2nd] - x[idxn] - n - d
            if val1 * val2 != 0:
                return False, n, d
    return True, None, None

