def find_max_m_fast():
    S = set(range(32, 1088))
    current_max = 1087
    while True:
        m = current_max + 1
        possible = True
        # The condition is: for all n in [32, (m-1024)//2], (n in S or m-n in S).
        for n in range(32, (m - 1024) // 2 + 1):
            if n not in S and (m - n) not in S:
                possible = False
                break
        if possible:
            S.add(m)
            current_max = m
        else:
            break
    return current_max

